import java.util.*;
import java.util.function.*;

public class Main {
    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int p = sc.nextInt();
        int k = sc.nextInt();

        int[] parent = new int[p];
        int[] componentSize = new int[p];
        for (int i = 0; i < p; i++) {
            parent[i] = i;
            componentSize[i] = 1;
        }

        Function<Integer, Integer> findRoot = new Function<Integer, Integer>() {
            public Integer apply(Integer u) {
                while (parent[u] != u) {
                    parent[u] = parent[parent[u]];
                    u = parent[u];
                }
                return u;
            }
        };

        BiConsumer<Integer, Integer> unionSets = new BiConsumer<Integer, Integer>() {
            public void accept(Integer u, Integer v) {
                u = findRoot.apply(u);
                v = findRoot.apply(v);
                if (u != v) {
                    componentSize[u] += componentSize[v];
                    parent[v] = u;
                }
            }
        };

        // fast_power function
        BiFunction<Long, Long, Long> fastPower = new BiFunction<Long, Long, Long>() {
            public Long apply(Long base, Long exp) {
                long res = 1;
                long b = base;
                long e = exp;
                while (e > 0) {
                    if ((e & 1) == 1) {
                        res = (res * b) % 1000000007;
                    }
                    b = (b * b) % 1000000007;
                    e >>= 1;
                }
                return res;
            }
        };

        // check_power function
        BiFunction<Long, Long, Long> checkPower = new BiFunction<Long, Long, Long>() {
            public Long apply(Long a, Long b) {
                long res = 1;
                long base = a;
                long exp = b;
                long p = 1000000007;
                while (exp > 0) {
                    if ((exp & 1) == 1) {
                        res = (res * base) % p;
                    }
                    base = (base * base) % p;
                    exp >>= 1;
                }
                return res == 1 ? p : 1;
            }
        };

        if (k == 0) {
            System.out.println(fastPower.apply((long) p, (long) p - 1));
            return;
        }

        for (int i = 0; i < p; i++) {
            parent[i] = i;
        }

        for (int i = 0; i < p; i++) {
            int v = (int)((long)k * i % p);
            unionSets.accept(i, v);
        }

        long result = 1;
        for (int i = 0; i < p; i++) {
            if (findRoot.apply(i) == i) {
                result = (result * checkPower.apply((long)k, (long)componentSize[i])) % 1000000007;
            }
        }

        System.out.println(result);
    }
}
